import { tags } from "typia";

import { IShoppingMallValidationMetadata } from "./IShoppingMallValidationMetadata";

/**
 * Comprehensive session validation response containing detailed authentication
 * status, user profile information, and platform context. This response
 * provides all necessary information for frontend applications to render
 * appropriate user interfaces and manage authenticated sessions effectively
 * across the shopping mall platform.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSessionValidation = {
  /**
   * Indicates whether the session is currently valid and authenticated. False
   * indicates an expired, invalid, or corrupted token that requires
   * re-authentication.
   */
  isValid: boolean;

  /**
   * Type of authenticated user in the shopping mall platform. Determines the
   * user's role, permissions, and available functionality across the
   * platform.
   */
  userType: "customer" | "seller" | "admin";

  /**
   * Unique identifier of the authenticated user across the platform. This ID
   * is consistent across all user types and serves as the primary user
   * reference throughout the system.
   */
  userId: string & tags.Format<"uuid">;

  /**
   * Unique session identifier linking to the active session record in the
   * appropriate session table (customer, seller, or admin sessions). Used for
   * session management and audit trails.
   */
  sessionId: string & tags.Format<"uuid">;

  /**
   * ISO 8601 timestamp indicating when the current session will expire. Used
   * by clients to manage token refresh and determine when re-authentication
   * is required.
   */
  expiresAt: string & tags.Format<"date-time">;

  /**
   * List of permission strings defining the authenticated user's capabilities
   * within the shopping mall platform. Permissions are role-based and control
   * access to specific features and operations.
   */
  permissions: string[];

  /**
   * Array of role identifiers assigned to the authenticated user. Roles
   * determine the user's access level and available functionality across
   * different platform modules.
   */
  roles: string[];

  /**
   * Additional session metadata including security information, activity
   * tracking, and device details. This data helps monitor account security
   * and provides context for session management decisions.
   */
  metadata: IShoppingMallValidationMetadata;
};
